1: function _authenticateCaller() internal view {
2:         // Each external function is dynamically assigned a role ID in the Authorizer as the hash of the Vault's address
3:         // and the function selector.
4:         bytes32 roleId = keccak256(abi.encodePacked(address(this), msg.sig));
5:         require(_authorizer.hasRole(roleId, msg.sender), "SENDER_NOT_ALLOWED");
6:     }

1: function _peek(bytes6 base, bytes6 kind) private view returns (uint accumulator, uint updateTime) {
2:         address source = sources[base][kind];
3:         require (source != address(0), "Source not found");
4: 
5:         if (kind == RATE.b6()) accumulator = CTokenInterface(source).borrowIndex();
6:         else if (kind == CHI.b6()) accumulator = CTokenInterface(source).exchangeRateStored();
7:         else revert("Unknown oracle type");
8: 
9:         require(accumulator > 0, "Compound accumulator is zero");
10: 
11:         updateTime = block.timestamp;
12:     }

